        private static string[] R(params string[] row) => row;

        private static Dictionary<string, string[]> Build(string[][] rows)
        {
            var table = new Dictionary<string, string[]>(rows.Length);
            foreach (string[] row in rows) table[row[0]] = row;
            return table;
        }
